function Sidebar({collapsed,mobile,view,user,notices,toggle,close,nav,ai}:any){const items=[[Grid2X2,"Home"],[FolderKanban,"Portfolio"],[Circle,"My work"],[Inbox,"Inbox"],[Users,"Teams"],[GitBranch,"Agents"],...(user?.role==="admin"&&user?.kind==="human"?[[Settings2,"Admin"] as const]:[])] as const;return <aside className={cn("fixed inset-y-0 left-0 z-20 flex w-64 flex-col border-r border-line bg-[#0c0c0f] transition-transform lg:visible lg:translate-x-0",mobile?"visible translate-x-0":"invisible -translate-x-full",collapsed&&"lg:w-[72px]")}><div className="flex h-16 items-center gap-3 px-4"><div className="grid h-8 w-8 place-items-center rounded-lg bg-accent font-black text-slate-950">E</div>{!collapsed&&<span className="font-semibold">Enter AI</span>}<button aria-label={collapsed?"Expand sidebar":"Collapse sidebar"} className="ml-auto hidden text-zinc-500 lg:block" onClick={toggle}>{collapsed?<ChevronRight size={16}/>:<ChevronLeft size={16}/>}</button><button aria-label="Close navigation" className="ml-auto lg:hidden" onClick={close}><X size={17}/></button></div><nav className="px-3">{items.map(([Icon,label])=><button key={label} aria-label={label} aria-current={view===label?"page":undefined} onClick={()=>nav(label)} className={cn("mb-1 flex w-full items-center gap-3 rounded-lg px-3 py-2 text-sm text-zinc-400 hover:bg-white/5",view===label&&"bg-sky-400/10 text-sky-300",collapsed&&"lg:justify-center lg:px-0")}><Icon size={17}/>{!collapsed&&label}{label==="Inbox"&&notices.some((x:any)=>!x.read)&&!collapsed&&<i className="ml-auto h-1.5 w-1.5 rounded-full bg-sky-400"/>}</button>)}<div className="my-4 h-px bg-line"/><button onClick={ai} className="flex w-full gap-3 rounded-lg bg-sky-400/10 px-3 py-2.5 text-sm text-sky-300"><Sparkles size={17}/>{!collapsed&&"Ask Enter AI"}</button></nav><div className="mt-auto border-t border-line p-3"><div className="flex gap-3 p-2"><Avatar user={user}/>{!collapsed&&<span className="text-sm">{user?.name||"Enter AI Admin"}</span>}</div></div></aside>}
function AuthShell({title,subtitle,children}:{title:string;subtitle:string;children:ReactNode}){return <main className="grid min-h-screen place-items-center bg-canvas p-4 sm:p-6"><Card className="w-full max-w-md p-6 shadow-glow sm:p-7"><div className="mb-6 flex gap-3"><div className="grid h-10 w-10 shrink-0 place-items-center rounded-xl bg-accent font-black text-slate-950">E</div><div className="min-w-0"><h1 className="font-semibold">{title}</h1><p className="text-xs text-zinc-500">{subtitle}</p></div></div>{children}</Card></main>}
function Notice({tone,children}:{tone:"error"|"ok";children:ReactNode}){return <p role={tone==="error"?"alert":"status"} className={cn("rounded-lg border p-3 text-sm",tone==="error"?"border-red-500/30 bg-red-500/10 text-red-200":"border-emerald-500/30 bg-emerald-500/10 text-emerald-200")}>{children}</p>}
